// Credits for every model and library in the game, shown on the Controls panel (Credits). `covers` lists the source folders or files (as recorded in props-assets.js and nature-assets.js)
// each entry accounts for: a test fails if a shipped model is not covered, so a new asset cannot ship without its credit. CC-BY items must say who made them, the licence and a link.
export const CREDITS=Object.freeze([
 {who:'Kenney',what:'City Kit (Suburban): the houses. City Kit (Commercial): the shops and offices. City Kit (Industrial): Eastbank Works (the warehouse, workshop, supplier and gas kiosk, shipping containers, a tank). Furniture Kit: the furniture inside the houses.',licence:'CC0 1.0',url:'https://kenney.nl',covers:['kenney-suburban/','kenney-commercial/','kenney-furniture/','kenney_city-kit-industrial_2.0/']},
 {who:'Quaternius',what:'Stylized Nature MegaKit (the trees), Ultimate Modular Men and Women (the characters), the farm buildings, the cars and the Hut.',licence:'CC0 1.0',url:'https://quaternius.com',covers:['quaternius-farm/','quaternius-cars/','polypizza/Hut_by_Quaternius.glb','nature/','characters/']},
 {who:'Poly Pizza',what:'The Store and the Wood Log (authors not recorded; both published for free use on Poly Pizza).',licence:'as published on Poly Pizza',url:'https://poly.pizza',covers:['polypizza/Store.glb','polypizza/Wood_Log.glb']},
 {who:'Aditya Graphical',what:'Low poly Pickup truck v3 (the Pevrolet Off Road Pickup). Used with the wheels separated from the body, its two textures merged into one and shrunk.',licence:'CC-BY-4.0',url:'https://sketchfab.com/3d-models/low-poly-pickup-truck-v3-de5b3f50a0e94dbf98be9584e01201ed',covers:['Veichles/low_poly_pickup_truck_v3/']},
 {who:'00amza',what:'Pickup Truck (the Worktruck). Used with the wheels separated from the body and its texture shrunk.',licence:'CC-BY-4.0',url:'https://sketchfab.com/3d-models/pickup-truck-047615f53e2d45b9a1a2a4dd203d459c',covers:['Veichles/green_pickup/']},
 {who:'The project owner',what:'The new sawmill (Sawmillv4), the pallets, boxes and crates, and the loading-zone props (bollard, unload and pickup signs, dock plate), and the gas-station props (gas and diesel pumps, nozzles, pump island, forecourt canopy) and the gas can: modelled by the project owner (authorship of the can still to be confirmed). Own work, not third-party assets.',licence:'own work',url:null,covers:['assets/Sawmillv4.glb','assets/pallet','assets/box-','assets/crate-','assets/zone-','assets/dock-plate','assets/fuel-','assets/pump-island','assets/forecourt-canopy','fuel_can/']},
 {who:'three.js',what:'The 3D engine (r160).',licence:'MIT',url:'https://threejs.org',covers:[]},
 {who:'meshoptimizer',what:'Mesh simplification used while converting models.',licence:'MIT',url:'https://github.com/zeux/meshoptimizer',covers:[]}
]);
export const creditFor=source=>CREDITS.find(c=>c.covers.some(prefix=>source.startsWith(prefix)))||null;
